from pathlib import Path
text = Path(r'{package}/SKILL.md').read_text(encoding='utf-8')
code = text.split('```python\n', 1)[1].split('\n```', 1)[0]
ns = {'__name__': 'recap_skill'}
exec(compile(code, 'SKILL.md:python:0', 'exec'), ns)
observed = {}
for label, value in [('missing', None), ('blank', ''), ('malformed', '[')]:
    try:
        ns['fragments_from_smiles'](value)
    except ValueError as exc:
        observed[label] = str(exc)
try:
    ns['terminal_fragments'](ns['Chem'].MolFromSmiles(''))
except ValueError as exc:
    observed['zero_atoms'] = str(exc)
import json
print(json.dumps(observed))

